import{_ as e,c as t,o as s,ag as r}from"./chunks/framework.Sr95JMjc.js";const o="/images/posts/aws-nlb-tls-ecdsa/01.png",n="/images/posts/aws-nlb-tls-ecdsa/02.png",l="/images/posts/aws-nlb-tls-ecdsa/03.png",m=JSON.parse('{"title":"AWS NLB ECDSA TLS 오프로드","description":"","frontmatter":{"title":"AWS NLB ECDSA TLS 오프로드","date":"2024-05-25T23:00+0900","tags":["AWS NLB","ECDSA"]},"headers":[],"relativePath":"posts/aws-nlb-tls-ecdsa.md","filePath":"posts/aws-nlb-tls-ecdsa.md","lastUpdated":1778195220000}'),c={name:"posts/aws-nlb-tls-ecdsa.md"};function i(p,a,d,h,g,b){return s(),t("div",null,[...a[0]||(a[0]=[r('<h4 id="aws-인증서-관련-히스토리" tabindex="-1">AWS 인증서 관련 히스토리 <a class="header-anchor" href="#aws-인증서-관련-히스토리" aria-label="Permalink to &quot;AWS 인증서 관련 히스토리&quot;">​</a></h4><ul><li><a href="https://aws.amazon.com/ko/about-aws/whats-new/2021/07/aws-certificate-manager-provides-expanded-usage-imported-ecdsa-rsa-certificates/" target="_blank" rel="noreferrer">AWS Certificate Manager, 가져온 ECDSA 및 RSA 인증서의 확장된 사용 제공</a></li><li><a href="https://aws.amazon.com/ko/about-aws/whats-new/2022/11/aws-certificate-manager-elliptic-curve-digital-signature-algorithm-tls-certificates/" target="_blank" rel="noreferrer">AWS Certificate Manager, 이제 Elliptic Curve Digital Signature Algorithm TLS 인증서 지원</a></li><li><a href="https://aws.amazon.com/ko/about-aws/whats-new/2024/01/network-load-balancer-rsa-3072-bit-ecdsa-256-384-521-bit-certificates/" target="_blank" rel="noreferrer">Network Load Balancer, 이제 AWS Certificate Manager를 통한 RSA 3072-비트, ECDSA 256/384/521-비트 인증서 지원</a></li></ul><p>위 기록처럼 2021년 7월 부터 AWS Certificate Manager에서 외부에서 발급된 ECDSA 인증서를 가져와서 등록할 수 있게 지원하였고 2022년 11월 부터는 ACM 자체적으로 ECDSA 인증서 발급을 지원한다. 그리고 시간이 흘러 2024년 1월부터는 <a href="https://aws.amazon.com/ko/about-aws/whats-new/2024/01/network-load-balancer-rsa-3072-bit-ecdsa-256-384-521-bit-certificates/" target="_blank" rel="noreferrer">Network Load Balancer 에서도 ECDSA 인증서 등록을 지원</a>한다.</p><p><img src="'+o+'" alt=""></p><blockquote><p>위 화면은 ACM 외부에서 발급된 ECDSA 인증서를 가져온 예시를 보여줍니다.</p></blockquote><h4 id="network-load-balancer-tls-리스너-구성" tabindex="-1">Network Load Balancer TLS 리스너 구성 <a class="header-anchor" href="#network-load-balancer-tls-리스너-구성" aria-label="Permalink to &quot;Network Load Balancer TLS 리스너 구성&quot;">​</a></h4><p>그동안 ELB 에서 ECDSA 인증서로 TLS 오프로드를 처리하기 위해서는 오직 ALB(Application Load Balancer)를 구성해야했다. 이제는 <code>NLB(Network Load Balancer)</code>로 구성하고 <a href="https://docs.aws.amazon.com/ko_kr/elasticloadbalancing/latest/network/create-tls-listener.html" target="_blank" rel="noreferrer">TLS 리스너</a>에서 ACM에 추가되어있는 <code>ECDSA 인증서</code>를 선택하여 구성할 수 있다.</p><p><img src="'+n+'" alt=""></p><blockquote><p>하지만, NLB가 TLS 리스너를 사용하는 경우 mTLS는 지원하지 못하는 구성이 되는 것은 일부 시스템에서 중요한 부분일 수 있습니다.</p></blockquote><h4 id="대상-그룹-프록시-프로토콜-v2" tabindex="-1">대상 그룹 - 프록시 프로토콜 v2 <a class="header-anchor" href="#대상-그룹-프록시-프로토콜-v2" aria-label="Permalink to &quot;대상 그룹 - 프록시 프로토콜 v2&quot;">​</a></h4><p>NLB 는 ALB와는 다르게 L4 레벨로 동작하므로 HTTP 트래픽을 HTTPS로 리다이렉트하는 것을 지원하지 못한다. ChatGPT에게 물어보더라도 TCP 리스너로 구성하고 Nginx와 같은 별도의 로드밸런서에서 TLS 오프로드를 처리함과 동시에 <code>Forward http to https</code> 를 적용하는 예시를 설명한다.</p><p>사내 엔지니어와 삽질을 해본결과 로드 밸런서에 연결되는 대상 그룹에서 <code>프록시 프로토콜 v2</code>를 활성화하면 Elastic Beanstalk의 Nginx 플랫폼에서 <a href="https://docs.nginx.com/nginx/admin-guide/load-balancer/using-proxy-protocol/" target="_blank" rel="noreferrer">PROXY Protocol</a>을 통해 <code>$proxy_protocol_server_port</code> 속성을 사용할 수 있음을 확인했다. 더 나아가서는 <code>$proxy_protocol_addr</code> 속성으로 실제로 트래픽을 전달한 <code>클라이언트 IP</code>를 액세스 로그에 출력하거나 <code>X-Forwarded-For</code> 헤더로 애플리케이션까지 전달할 수 있어보인다.</p><p><img src="'+l+`" alt=""></p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>http {</span></span>
<span class="line"><span>    server {</span></span>
<span class="line"><span>        listen 80 proxy_protocol;</span></span>
<span class="line"><span>        if ($proxy_protocol_server_port = 80) {</span></span>
<span class="line"><span>            return 301 https://$host$request_uri;</span></span>
<span class="line"><span>        }</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><blockquote><p>NLB 에서 Nginx로 전달할 때 사용한 포트가 80 이라면 HTTP 요청으로 간주하고 HTTPS 요청으로 전달될 수 있도록 301 응답을 처리했습니다.</p></blockquote>`,15)])])}const w=e(c,[["render",i]]);export{m as __pageData,w as default};
